Port this Python function to C++.

```python
def two_sum(nums, target):
    seen = {}
    for i, x in enumerate(nums):
        if target - x in seen:
            return [seen[target - x], i]
        seen[x] = i
    return []
```

Here's the C++ equivalent:

```cpp
vector<int> twoSum(const vector<int>& nums, int target) {
    unordered_map<int, int> seen;
    for (int i = 0; i < (int)nums.size(); i++) {
        auto it = seen.find(target - nums[i]);
        if (it != seen.end()) return {it->second, i};
        seen[nums[i]] = i;
    }
    return {};
}
```

The logic is the same as the Python version. Pass large containers by const reference (as here) to avoid copying them. For example, `two_sum([2, 7, 11, 15], 9)` gives `0 1` in both versions.

Explain union-find with an example. When is it better than BFS?

```python
class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
    def find(self, x):
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x
    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return False
        if self.size[ra] < self.size[rb]:
            ra, rb = rb, ra
        self.parent[rb] = ra
        self.size[ra] += self.size[rb]
        return True

d = DSU(6)
for a, b in [(0, 1), (1, 2), (3, 4), (2, 0)]:
    print(a, b, d.union(a, b))
print(len({d.find(i) for i in range(6)}))
```
